theme:check.description:
Calls and runs "Theme Check" (https://shopify.dev/docs/themes/tools/theme-check) to analyze your theme code for errors and to ensure that it follows theme and Liquid best practices. "Learn more about the checks that Theme Check runs." (https://shopify.dev/docs/themes/tools/theme-check/checks)

Use `--json-schema` to print the result, error, and event schemas.

Output from `--json` conforms to the `ThemeCheckResult` schema.

```json
{
  "anyOf": [
    {
      "$ref": "#/definitions/ThemeEnvironment/anyOf/0/properties/result"
    },
    {
      "type": "object",
      "properties": {
        "environments": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/ThemeEnvironment"
          }
        }
      },
      "required": [
        "environments"
      ],
      "additionalProperties": false
    }
  ],
  "title": "ThemeCheckResult",
  "definitions": {
    "ThemeCheckIssue": {
      "type": "object",
      "properties": {
        "filePath": {
          "type": "string",
          "description": "The absolute native path of the file."
        },
        "check": {
          "type": "string"
        },
        "severity": {
          "type": "string",
          "enum": [
            "error",
            "warning",
            "info"
          ]
        },
        "startRow": {
          "type": "integer",
          "exclusiveMinimum": 0,
          "description": "The one-based starting line."
        },
        "startColumn": {
          "type": "integer",
          "exclusiveMinimum": 0,
          "description": "The one-based starting column."
        },
        "endRow": {
          "type": "integer",
          "exclusiveMinimum": 0,
          "description": "The one-based ending line."
        },
        "endColumn": {
          "type": "integer",
          "exclusiveMinimum": 0,
          "description": "The one-based ending column."
        },
        "message": {
          "type": "string"
        }
      },
      "required": [
        "filePath",
        "check",
        "severity",
        "startRow",
        "startColumn",
        "endRow",
        "endColumn",
        "message"
      ],
      "additionalProperties": false
    },
    "ThemeEnvironment": {
      "anyOf": [
        {
          "type": "object",
          "properties": {
            "environment": {
              "type": "string"
            },
            "result": {
